export default {
  async fetch(request, env) {
    const url = new URL(request.url);
    if (url.pathname === '/api/data') {
      if (request.method === 'PUT') {
        const data = await request.json();
        await env.ONBOARDING_KV.put('data', JSON.stringify(data));
        return new Response('{"ok":true}', { headers: { 'Content-Type': 'application/json' } });
      }
      const raw = await env.ONBOARDING_KV.get('data');
      const data = raw ? raw : JSON.stringify(DEFAULT_DATA);
      return new Response(data, { headers: { 'Content-Type': 'application/json', 'Cache-Control': 'no-store' } });
    }
    let raw = await env.ONBOARDING_KV.get('data');
    if (!raw) { raw = JSON.stringify(DEFAULT_DATA); await env.ONBOARDING_KV.put('data', raw); }
    const safeJson = raw.replace(/<\/script>/gi, '<\\/script>');
    const html = HTML.replace('__INITIAL_DATA__', safeJson);
    return new Response(html, { headers: { 'Content-Type': 'text/html; charset=utf-8' } });
  }
};

